import React, { useRef, useEffect } from 'react';

export default function Orb3D({ size = 280, colors = ['#6040c0','#3020a0','#8060e0'], speed = 0.4, morphing = true }) {
  const canvasRef = useRef(null);
  const raf       = useRef(null);
  const t         = useRef(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const S = size;
    canvas.width  = S;
    canvas.height = S;

    const draw = () => {
      t.current += 0.008 * speed;
      ctx.clearRect(0, 0, S, S);

      const cx = S / 2, cy = S / 2;
      const r  = S * 0.42;

      // Morphing radii — subtle organic wobble
      const wobble = morphing ? (
        idx => {
          const angle = (idx / 8) * Math.PI * 2 + t.current;
          return r + Math.sin(angle * 2.5 + t.current * 0.7) * (r * 0.06)
                   + Math.cos(angle * 1.8 + t.current * 1.1) * (r * 0.04);
        }
      ) : () => r;

      // Build morphing path
      ctx.beginPath();
      const pts = 64;
      for (let i = 0; i <= pts; i++) {
        const angle = (i / pts) * Math.PI * 2;
        const wr    = morphing
          ? r + Math.sin(angle * 3 + t.current * 0.8) * (r * 0.055)
              + Math.cos(angle * 2 + t.current * 1.2) * (r * 0.035)
          : r;
        const x = cx + Math.cos(angle) * wr;
        const y = cy + Math.sin(angle) * wr;
        i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.closePath();

      // Deep base gradient
      const baseGrad = ctx.createRadialGradient(cx - r*0.3, cy - r*0.3, r*0.05, cx, cy, r*1.05);
      baseGrad.addColorStop(0, colors[2] || '#8060e0');
      baseGrad.addColorStop(0.45, colors[0] || '#6040c0');
      baseGrad.addColorStop(1, colors[1] || '#1a0e40');
      ctx.fillStyle = baseGrad;
      ctx.fill();

      // Specular highlight — moves slowly
      const hx = cx - r * (0.28 + Math.sin(t.current * 0.5) * 0.06);
      const hy = cy - r * (0.28 + Math.cos(t.current * 0.4) * 0.05);
      const specGrad = ctx.createRadialGradient(hx, hy, 0, hx, hy, r * 0.55);
      specGrad.addColorStop(0, 'rgba(255,255,255,0.35)');
      specGrad.addColorStop(0.4, 'rgba(255,255,255,0.06)');
      specGrad.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = specGrad;
      ctx.fill();

      // Secondary soft highlight
      const h2x = cx + r * 0.18, h2y = cy - r * 0.1;
      const sg2 = ctx.createRadialGradient(h2x, h2y, 0, h2x, h2y, r * 0.3);
      sg2.addColorStop(0, 'rgba(180,160,255,0.18)');
      sg2.addColorStop(1, 'rgba(180,160,255,0)');
      ctx.fillStyle = sg2;
      ctx.fill();

      // Dark depth shadow at bottom-right
      const shGrad = ctx.createRadialGradient(cx + r*0.3, cy + r*0.35, 0, cx + r*0.3, cy + r*0.35, r * 0.7);
      shGrad.addColorStop(0, 'rgba(0,0,0,0.45)');
      shGrad.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = shGrad;
      ctx.fill();

      // Orbiting ring — dashed
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(t.current * 0.3);
      ctx.scale(1, 0.35);
      ctx.beginPath();
      ctx.arc(0, 0, r * 1.12, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(255,255,255,0.12)';
      ctx.lineWidth = 1;
      ctx.setLineDash([6, 8]);
      ctx.stroke();
      ctx.restore();

      // Drop shadow glow (drawn as ellipse below)
      const glowGrad = ctx.createRadialGradient(cx, cy + r * 0.9, 0, cx, cy + r * 0.9, r * 0.7);
      glowGrad.addColorStop(0, `${colors[0]}44` || 'rgba(96,64,192,0.26)');
      glowGrad.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.beginPath();
      ctx.ellipse(cx, cy + r * 0.92, r * 0.65, r * 0.18, 0, 0, Math.PI * 2);
      ctx.fillStyle = glowGrad;
      ctx.fill();

      raf.current = requestAnimationFrame(draw);
    };

    draw();
    return () => cancelAnimationFrame(raf.current);
  }, [size, colors, speed, morphing]);

  return <canvas ref={canvasRef} style={{ display:'block', width:size, height:size, maxWidth:'100%' }} />;
}
